export function useReorder(items: Item[]) {
  const [order, setOrder] = useState(items.map((i) => i.id));

  const move = useCallback((from: number, to: number) => {
    setOrder((prev) => {
      const next = prev.slice();
      const [moved] = next.splice(from, 1);
      next.splice(to, 0, moved);
      return next;
    });
  }, []);

  return { order, move };
}

def monthly_report(entries: list[Entry], month: str) -> dict[str, Decimal]:
    totals: dict[str, Decimal] = defaultdict(Decimal)
    for entry in entries:
        if not entry.date.startswith(month):
            continue
        for posting in entry.postings:
            totals[posting.account] += posting.amount
    return dict(sorted(totals.items(), key=lambda kv: kv[1]))

export function exportPng(layers, scale = 1) {
  const canvas = document.createElement('canvas');
  canvas.width = layers.width * scale;
  canvas.height = layers.height * scale;
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(layers.toOffscreen(), 0, 0, canvas.width, canvas.height);
  return canvas.toDataURL('image/png');
}
